# MToP's own getFun_CEC21_MTMO computes these differently from the CEC 2021
# definition, so its numbers are not the target:
#
#   Modified Schwefel  writes `if abs(z) <= 500` where z is a whole column.
#                      MATLAB's if on an array is true only when every element
#                      is, so the branch is chosen once per column instead of
#                      per element. Reached by gType F11, F17 and F22.
#   Schaffer F6        writes x4(mod(i,n4)+1), a linear index into the
#                      flattened matrix, so the wrap-around neighbour collapses
#                      to one scalar. Reached by gType F19.
#   Discus             writes sum(x2(2:end).^2, 2), which flattens to a row and
#                      sums to a single scalar added to every sample.
#   ExGriewRosen       writes x3(size(x3,2)) for the last column, another
#                      linear index, in gType F20 and F22 but not in F15.
#
# Replicating each quirk in Python reproduces MToP bit for bit, which is how
# they were pinned down; the values kept here are this platform's own.
DIVERGES = {
    "CEC21_MTMO_CPLX1": "modified Schwefel, whole-column if",
    "CEC21_MTMO_CPLX2": "Schaffer F6, linear index",
    "CEC21_MTMO_CPLX3": "modified Schwefel and ExGriewRosen",
    "CEC21_MTMO_CPLX8": "Discus and ExGriewRosen, linear index",
    "CEC21_MTMO_CPLX9": "modified Schwefel, whole-column if",
    "CEC21_MTMO_CPLX10": "ExGriewRosen, linear index",
}


