def probe(lower, upper, task_index):
    """The same three points MATLAB builds, in the task's own box."""
    D = len(lower)
    a = np.arange(3)[:, None]
    b = np.arange(D)[None, :]
    frac = ((a * 7 + b * 13 + task_index * 5) % 97 + 0.5) / 97
    return lower + frac * (upper - lower)


def evaluate(name, t):
    mod_name, cls_name, meth = MTOP[name][:3]
    mod = importlib.import_module(f"ddmtolab.Problems.MTMO.{mod_name}")
    problem = getattr(getattr(mod, cls_name)(), meth)()
    info = problem.get_task_info(t)
    lower = np.ravel(info["lower_bounds"]).astype(float)
    upper = np.ravel(info["upper_bounds"]).astype(float)
    obj, con = problem.evaluate_task(t, probe(lower, upper, t))
    return info, obj, con


@pytest.mark.parametrize("name", sorted(n for n in MTOP if n not in DIVERGES))
def test_matches_mtop(name):
    for t, (D, M, want_obj, want_con) in enumerate(MTOP[name][3]):
        info, obj, con = evaluate(name, t)
        assert info["dimension"] == D, f"{name} task {t + 1} dimension"
        assert info["n_objectives"] == M, f"{name} task {t + 1} objective count"
        assert np.allclose(obj.ravel(), want_obj, rtol=1e-11, atol=1e-11),             f"{name} task {t + 1} objectives"
        assert np.allclose(con.ravel(), want_con, rtol=1e-11, atol=1e-11),             f"{name} task {t + 1} constraints"


@pytest.mark.parametrize("name", sorted(DIVERGES))
def test_definitions_match_mtop_and_objectives_hold_still(name):
    """The definitions line up; only the landscape MToP computes is off, so the
    shape is checked against MToP and the objectives against our own values."""
    for t, (D, M, _, want_con) in enumerate(MTOP[name][3]):
        info, obj, con = evaluate(name, t)
        assert info["dimension"] == D
        assert info["n_objectives"] == M
        assert np.allclose(con.ravel(), want_con, rtol=1e-11, atol=1e-11)
        assert np.allclose(obj.ravel(), OWN_OBJECTIVES[name][t], rtol=1e-11, atol=1e-11),             f"{name} task {t + 1} objectives moved"


def test_modified_schwefel_branches_per_element():
    """The CEC definition picks the branch per variable, which is what makes
    this platform differ from MToP on F11, F17 and F22."""
    from ddmtolab.Problems.MTMO.cec21_mtmo import CEC21MTMOFunctions as F

    # one row inside the |z| <= 500 band, one outside, in the same column
    x = np.array([[0.0], [900.0]])
    got = F._modified_schwefel(x, 1)

    z = x[:, 0] + 4.209687462275036e02
    inside = z[0] * np.sin(np.abs(z[0]) ** 0.5)
    t = 500 - np.mod(z[1], 500)
    outside = t * np.sin(np.abs(t) ** 0.5) - ((z[1] - 500) ** 2) / (10000 * 1)
    assert np.isclose(got[0], 418.9829 - inside)
    assert np.isclose(got[1], 418.9829 - outside)
